input.command:
cd /app; python3 - <<'EOF'
import json
def load(f): return json.load(open(f))
def mean_all(*fs):
    u=[x for f in fs for x in load(f)['per_unit']]; return sum(u)/len(u)
base=mean_all('s_release.json','s_releaseb.json')
q={1:mean_all('s_ck1.json'),2:mean_all('s_ck2.json'),3:mean_all('s_ck3.json'),
   4:mean_all('s_ck4.json','s_ck4b.json'),5:mean_all('s_ck5.json')}
o={i:mean_all(f's_h{i}.json') for i in range(1,6)}
print("baseline",round(base,4))
for i in range(1,6): print(f"H-{i}: quality={q[i]-base:+.3f} offset={o[i]-base:+.3f}")
print("sum q+o", sum(q[i]-base for i in q)+sum(o[i]-base for i in o), "previous all-reverted delta", mean_all('s_prev.json')-base)
q4=q[4]-base
report={"culprit":"H-4","effect":{"lo":round(q4-0.2,2),"hi":round(q4+0.2,2)},
        "harness_only":[f"H-{i}" for i in range(1,6) if abs(q[i]-base)<=0.30 and abs(o[i]-base)>=0.90]}
json.dump(report,open('report.json','w'),indent=1); print(json.dumps(report))
EOF
